// Every rule that decides whether the bot may touch anything lives here.
// The LLM is not involved: this is plain code you can read and test.
const ALLOWED_ALERTS = ["OrdersApiDown"];
const SERVICE = "orders-api";
const CONTAINER = "firebreak-api-1";
const MAX_ATTEMPTS = 2;
const WINDOW_MS = 60 * 60 * 1000;
const COOLDOWN_MS = 5 * 60 * 1000;
// Set on import from FIREBREAK_REMEDIATION_DRY_RUN (default true).
const DRY_RUN = __REMEDIATION_DRY_RUN__;

const body = $json.body || {};
const labels = body.commonLabels || {};
const annotations = body.commonAnnotations || {};
const decision = {
  alertname: labels.alertname || "unknown",
  status: body.status || "unknown",
  container: CONTAINER,
  max_attempts: MAX_ATTEMPTS,
  runbook_url: annotations.runbook_url || "",
};

const allowed = decision.status === "firing"
  && ALLOWED_ALERTS.includes(decision.alertname)
  && labels.service === SERVICE;
if (!allowed) {
  return { json: { ...decision, action: "ignore", reason: "not on the allowlist" } };
}

// Survives between executions, but only when the workflow is published.
const state = $getWorkflowStaticData("global");
const now = Date.now();
state.attempts = (state.attempts || []).filter((t) => now - t < WINDOW_MS);

// Alertmanager repeats notifications for the same incident. The incident is
// identified by when its alerts started firing.
const incident = (body.alerts || []).map((a) => a.startsAt).sort()[0] || "unknown";
if (incident === state.lastIncident) {
  return { json: { ...decision, action: "skip", reason: "already handled this incident" } };
}

if (state.attempts.length >= MAX_ATTEMPTS) {
  return { json: { ...decision, action: "escalate", attempt: state.attempts.length,
    reason: `${MAX_ATTEMPTS} automatic restarts in the last hour did not fix it` } };
}

// A new incident this soon after a restart is a crash loop: restarting again
// would hide it, so a human takes over.
const last = state.attempts[state.attempts.length - 1];
if (last && now - last < COOLDOWN_MS) {
  const minutes = Math.round((now - last) / 60000);
  return { json: { ...decision, action: "escalate", attempt: state.attempts.length,
    reason: `it failed again ${minutes} min after my last restart (crash loop)` } };
}

// Dry runs count as attempts too, so the limit can be tested safely.
state.attempts.push(now);
state.lastIncident = incident;
return {
  json: { ...decision, action: DRY_RUN ? "dry_run" : "restart", attempt: state.attempts.length },
};

